import{_ as o,a0 as n,w as s,s as p,ao as g,I as l,x as i,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 有問必答：如何改變libvirt VM鏡像的默認位置 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何改變libvirt VM鏡像的默認位置 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何改變libvirt VM鏡像的默認位置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何改變libvirt VM鏡像的默認位置 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141014 Linux FAQs with Answers--How to change default location of libvirt VM images","title":"Linux 有問必答：如何改變libvirt VM鏡像的默認位置","tag":"201411","desc":""},"relativePath":"201411/20141014 Linux FAQs with Answers--How to change default location of libvirt VM images.md","filePath":"[post].md"}'),m={name:"201411/20141014 Linux FAQs with Answers--How to change default location of libvirt VM images.md"};function d(u,t,f,c,b,v){const e=n("Link");return s(),p("div",null,[t[11]||(t[11]=g(`<h1 id="linux-有問必答-如何改變libvirt-vm鏡像的默認位置" tabindex="-1">Linux 有問必答：如何改變libvirt VM鏡像的默認位置 <a class="header-anchor" href="#linux-有問必答-如何改變libvirt-vm鏡像的默認位置" aria-label="Permalink to “Linux 有問必答：如何改變libvirt VM鏡像的默認位置”">​</a></h1><blockquote><p><strong>提問</strong>： 我使用libvirt和virt-manager在我的Linux系統上創建虛擬機。我注意到虛擬機鏡像位於/var/lib/libvirt/images目錄。有沒有辦法改變虛擬機鏡像的默認路徑？</p></blockquote><p><strong>libvirt</strong>和它的GUI前端<strong>virt-manager</strong>可以使用不同的虛擬機管理程序創建和管理VM，例如LVM和Xen。默認上所有的虛擬機鏡像通過<strong>libvirt</strong>創建到/var/lib/libvirt/images目錄。然而，這有時並不是我們希望的。比如/var/lib/libvirt/images此處的磁盤分區大小有限。或者你想要存儲所有的虛擬機鏡像到一個特定的用於管理的倉庫中。</p><p>實際上，你可以非常容易地改變libvirt鏡像的默認目錄，或者稱之為“存儲池”。</p><p>有兩種方法可以改變默認存儲池。</p><h3 id="方法一-virt-manager-gui" tabindex="-1">方法一: Virt-Manager GUI <a class="header-anchor" href="#方法一-virt-manager-gui" aria-label="Permalink to “方法一: Virt-Manager GUI”">​</a></h3><p>如果你正在使用virt-manager GUI程序，改變默認存儲池非常容易。</p><p>進入<strong>virt-manager</strong>的菜單GUI “編輯” -&gt; &quot;連接細節&quot;。</p><p><img src="https://farm4.staticflickr.com/3935/15433062592_0d89a8d132_o.png" alt=""></p><p>你可以看到如下所是的默認存儲池。在窗口的左下角，點擊叉形按鈕，將會停止默認的存儲池。存儲池一旦停止後，點擊右邊的垃圾桶，將會刪除存儲池。<strong>注意這個動作不會刪除池中的鏡像。</strong></p><p>現在點擊左邊的加號增加一個新的存儲池。</p><p><img src="https://farm6.staticflickr.com/5600/15246703330_26884c8258_b.jpg" alt=""></p><p>輸入新的存儲池的名字（比如：default），並且選擇存儲池的類型。本例中，因為我們只是改變存儲池目錄所以選擇“文件系統目錄”。</p><p><img src="https://farm4.staticflickr.com/3928/15433416355_1a2f9f85ab_b.jpg" alt=""></p><p>輸入新的存儲池路徑（比如，/storage）。</p><p><img src="https://farm6.staticflickr.com/5599/15433062732_195fa6701b_b.jpg" alt=""></p><p>這時，新的存儲池應該啓動了，並且自動在你創建一個新的虛擬機的時候使用。</p><p><img src="https://farm4.staticflickr.com/3934/15430217721_b14c3a93fa_b.jpg" alt=""></p><h3 id="方法二-virsh-命令列" tabindex="-1">方法二: Virsh 命令列 <a class="header-anchor" href="#方法二-virsh-命令列" aria-label="Permalink to “方法二: Virsh 命令列”">​</a></h3><p>另外一個改變默認存儲池目錄的方法是使用來自<strong>libvirt</strong>包的<strong>virsh</strong> 命令列工具。</p><p>首先，運行下面的命令來導出默認存儲池的XML定義。</p><pre><code> $ virsh pool-dumpxml default &gt; pool.xml 
</code></pre><p>用文本編輯器打開XML文件，並且改變<code>&lt;path&gt;</code>節點中的/var/lib/libvirt/images改成新的地址。</p><pre><code>&lt;pool type=&#39;dir&#39;&gt;
  &lt;name&gt;default&lt;/name&gt;
  &lt;uuid&gt;0ec0e393-28a2-e975-feec-0c7356f38d08&lt;/uuid&gt;
  &lt;capacity unit=&#39;bytes&#39;&gt;975762788352&lt;/capacity&gt;
  &lt;allocation unit=&#39;bytes&#39;&gt;530052247552&lt;/allocation&gt;
  &lt;available unit=&#39;bytes&#39;&gt;445710540800&lt;/available&gt;
  &lt;source&gt;
  &lt;/source&gt;
  &lt;target&gt;
    &lt;path&gt;/var/lib/libvirt/images&lt;/path&gt;
    &lt;permissions&gt;
      &lt;mode&gt;0711&lt;/mode&gt;
      &lt;owner&gt;-1&lt;/owner&gt;
      &lt;group&gt;-1&lt;/group&gt;
    &lt;/permissions&gt;
  &lt;/target&gt;
&lt;/pool&gt;
</code></pre><p>移除現在的默認池。</p><pre><code>$ virsh pool-destroy default 
</code></pre><hr><pre><code>Pool default destroyed
</code></pre><p>現在創建一個基於更新後的XML文件的新存儲池。</p><pre><code>$ virsh pool-create pool.xml 
</code></pre><hr><pre><code>Pool default created from pool.xml
</code></pre><p>這時，默認池已經改變到新的地址了，並且可以使用了。</p><hr>`,34)),l("p",null,[t[1]||(t[1]=i("via: ",-1)),r(e,{href:"http://ask.xmodulo.com/change-default-location-libvirt-vm-images.html"},{default:a(()=>[...t[0]||(t[0]=[i("http://ask.xmodulo.com/change-default-location-libvirt-vm-images.html",-1)])]),_:1})]),l("p",null,[t[4]||(t[4]=i("譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[2]||(t[2]=[i("geekpi",-1)])]),_:1}),t[5]||(t[5]=i(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=i("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[i("LCTT",-1)])]),_:1}),t[9]||(t[9]=i(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[i("Linux中國",-1)])]),_:1}),t[10]||(t[10]=i(" 榮譽推出",-1))])])}const L=o(m,[["render",d]]);export{_ as __pageData,L as default};
